INSERT INTO `protocols` (id, name, parameters, bulk_modifier, description, observable, reportable, multiplier) VALUES
  (1, 'Dump resource', 1, 100, '[R 1 perform]: Dump one unit of resource R into space.', 1, 1, 0),
