INSERT INTO `queries` (id, name, description, parameters, script) VALUES
  (100, 'Get company name', '[N R L 100 query]: Returns the name for company N.', 1, 'SELECT users.name FROM users WHERE (((users.user_id)=[value_1]));'),
  (101, 'Get company credits', '[N R L 101 query]: Returns the number of credits in the company''s bank account were Company ID = N.', 1, 'SELECT users.credits FROM users WHERE (((users.user_id)=[value_1]));'),
  (110, 'List company spacecraft', '[N R L 110 query]: Returns a list of the IDs for the spacecraft that are owned by company N.', 1, 'SELECT agents.agent_id FROM agents WHERE (((agents.user_id)=[value_1])) ORDER BY agents.agent_id;'),
  (200, 'Get spacecraft name', '[N R L 200 query]: Returns the spacecraft name [30] for Spacraft ID N.', 1, 'SELECT agents.name FROM agents WHERE (((agents.agent_id)=[value_1]));'),
  (201, 'Get spacecraft owner', '[N R L 201 query]: Return the Company ID of the compony that owns Spacecraft ID N.', 1, 'SELECT agents.user_id FROM agents WHERE (((agents.agent_id)=[value_1]));'),
  (202, 'Get spaecraft location', '[N R L 202 query]: Returns the location ID of spacecraft N.', 1, 'SELECT object_id FROM agents WHERE agent_id = [value_1];'),
  (203, 'Get spacecraft hull type', '[N R L 203 query]: Retuns the hull type of spacecraft N.', 1, 'SELECT hull_type FROM agents WHERE agent_id=[value_1];'),
  (204, 'Get cargo mass', '[N R L 204 query]: Returns the total cargo mass in kg of spacecraft N.', 1, 'SELECT IFNULL(SUM(i.units * r.mass), 0) FROM sqInventory AS i INNER JOIN resources AS r ON r.id = i.resource WHERE i.drone = [value_1];'),
  (205, 'Get my spacecraft ID', '[R L 205 query]: Returns the spacecraft ID of the requesting spacecraft.', 0, 'SELECT agent_id FROM agents WHERE agent_id = [drone_id];'),
  (210, 'List spacecraft inventory', '[N R L 210 query]: Lists the resources and quantities in the cargo hold of spacecraft N.', 1, 'SELECT resource, units FROM sqInventory WHERE drone = [value_1] AND units > 0 ORDER BY units DESC;'),
  (212, 'Get resource quantity', '[N R L 212 query]: Returns how many units of resource N are in the requesting spacecraft''s cargo hold.', 1, 'SELECT IFNULL(MAX(units), 0) FROM sqInventory WHERE drone = [drone_id] AND resource = [value_1];'),
  (300, 'Get hull type name', '[N R L 300 query]: Returns the name of hull type N.', 1, 'SELECT name FROM hulls WHERE id=[value_1];'),
  (301, 'Get hull type cargo capacity', '[N R L 301 query]: Returns the cargo capacity in kg of hull type N.', 1, 'SELECT cargo_capacity FROM hulls WHERE id=[value_1];'),
  (400, 'Get resource name', '[N R L 400 query]: Retuns the name of resource N.', 1, 'SELECT name FROM resources WHERE id=[value_1];'),
  (401, 'Get resource unit mass', '[N R L 401 query]: Retuns the unit mass in kg of resource N.', 1, 'SELECT mass FROM resources WHERE id=[value_1];'),
  (410, 'List best extraction sites', '[N R L 410 query]: Returns the top extraction sites and abundancies for the resource N.', 1, 'SELECT location, multiplier FROM abundancies WHERE resource=[value_1] ORDER BY multiplier DESC;'),
  (500, 'Get protocol name', '[N R L 500 query]: Returns the name of protocol N.', 1, 'SELECT name FROM protocols WHERE id = [value_1];'),
  (501, 'Get protocol duration', '[N R L 501 query]: Returns the duration in minutes of protocol N.', 1, 'SELECT MAX(time) FROM (SELECT time FROM resource_effects WHERE protocol = [value_1] UNION SELECT time FROM market_effects WHERE protocol = [value_1]) AS combined;'),
  (510, 'List consumed resources', '[N R L 510 query]: Lists the resources and quantities that are consumed by protocol N.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=1 AND locked=0 ORDER BY quantity DESC;'),
  (511, 'List produced resources', '[N R L 511 query]: Lists the resources and quantities that are produced by protocol N.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=0 AND locked=0 ORDER BY quantity DESC;'),
  (512, 'List retained resources', '[N R L 512 query]: Lists the resources and quantities that are used by the protocol but returned when done.', 1, 'SELECT resource, quantity FROM resource_effects WHERE protocol=[value_1] AND deplete=0 AND locked=1 ORDER BY quantity DESC;'),
  (520, 'List consuming protocols', '[N R L 520 query]: Lists all the protocols and qantities that deplete resource N.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 1 AND locked = 0 ORDER BY quantity DESC;'),
  (521, 'List producing protocols', '[N R L 521 query]: Lists all the procedures and quantities that produce resource N.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 0 AND locked = 0 ORDER BY quantity DESC;'),
  (522, 'List retaining protocols', '[N R L 522 query]: Lists all the protocols and quatities that use resource N without consuming it.', 1, 'SELECT protocol, quantity FROM resource_effects WHERE resource = [value_1] AND deplete = 0 AND locked = 1 ORDER BY quantity DESC;'),
  (600, 'List local buy orders', '[N R L 600 query]: Lists buy orders for resource N at the requesting spacecraft''s location: price, wanted maximum, units held, spacecraft ID.', 1, 'SELECT o.new_credits, o.new_quantity, IFNULL(i.units, 0), o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 5 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id INNER JOIN agents AS a ON a.agent_id = o.drone AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE IFNULL(i.units, 0) < o.new_quantity ORDER BY o.new_credits DESC;'),
  (601, 'List solar buy orders', '[N R L 601 query]: Lists buy orders for resource N anywhere in the solar system: price, wanted maximum, units held, spacecraft ID.', 1, 'SELECT o.new_credits, o.new_quantity, IFNULL(i.units, 0), o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 5 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE IFNULL(i.units, 0) < o.new_quantity ORDER BY o.new_credits DESC;'),
  (610, 'List local sell orders', '[N R L 610 query]: Lists sell orders for resource N at the requesting spacecraft''s location: price, kept minimum, units held, spacecraft ID.', 1, 'SELECT o.new_credits, o.new_quantity, i.units, o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 4 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id INNER JOIN agents AS a ON a.agent_id = o.drone AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE i.units > o.new_quantity ORDER BY o.new_credits ASC;'),
  (611, 'List solar sell orders', '[N R L 611 query]: Lists sell orders for resource N anywhere in the solar system: price, kept minimum, units held, spacecraft ID.', 1, 'SELECT o.new_credits, o.new_quantity, i.units, o.drone FROM events AS o INNER JOIN (SELECT MAX(id) AS id FROM events WHERE outcome = 1 AND event_type = 4 AND resource = [value_1] GROUP BY drone) AS l ON l.id = o.id LEFT JOIN sqInventory AS i ON i.drone = o.drone AND i.resource = [value_1] WHERE i.units > o.new_quantity ORDER BY o.new_credits ASC;'),
  (700, 'Get location name', '[N R L 700 query]: Returns the name of location ID N.', 1, 'SELECT object_name FROM objects WHERE object_id=[value_1];'),
  (701, 'Get location type', '[N R L 701 query]: Returns the location type of location N.', 1, 'SELECT object_type FROM objects WHERE object_id=[value_1];'),
  (702, 'Get central body', '[N R L 702 query]: Retuns the location ID for the body around which N is orbiting.', 1, 'SELECT central_body_object_id FROM objects WHERE object_id=[value_1];'),
  (703, 'Get location coordinates', '[N R L 703 query]: Retuns the x, y, and z coordinates of location N.', 1, 'SELECT objects.x_coord, objects.y_coord, objects.z_coord FROM objects WHERE object_id=[value_1];'),
  (710, 'List orbiting bodies', '[N R L 710 query]: Returns a list of the object IDs that are in orbit around object N.', 1, 'SELECT object_id FROM objects WHERE central_body_object_id=[value_1];'),
  (720, 'List local spacecraft', '[N R L 720 query]: Lists all the drones at location N.', 1, 'SELECT agent_id FROM agents WHERE object_id =[value_1]'),
  (730, 'List local resources', '[N R L 730 query]: Returns the resource ID and abundancy value of each resource that can be recovered from the location.', 1, 'SELECT resource, multiplier FROM abundancies WHERE location=[value_1] ORDER BY multiplier DESC;'),
  (800, 'List personal events', '[N R L 800 query]: Lists the most recent events that affected spacecraft N.', 1, 'SELECT id FROM events WHERE outcome = 1 AND drone = [value_1] ORDER BY timestamp DESC, id DESC;'),
  (801, 'List local events', '[R L 801 query]: Lists the most recent events at the requesting spacecraft''s location.', 0, 'SELECT e.id FROM events AS e INNER JOIN agents AS a ON a.agent_id = e.drone WHERE e.outcome = 1 AND a.object_id = (SELECT object_id FROM agents WHERE agent_id = [drone_id]) ORDER BY e.timestamp DESC, e.id DESC;'),
  (802, 'List solar events', '[R L 802 query]: Lists the most recent events anywhere in the solar system.', 0, 'SELECT id FROM events WHERE outcome = 1 ORDER BY timestamp DESC, id DESC;'),
  (810, 'Get event type', '[N R L 810 query]: Get the type ID for event N.', 1, 'SELECT event_type FROM events WHERE outcome=1 AND id=[value_1];'),
  (811, 'Get event type name', '[N R L 811 query]: Returns the name of the type of event N.', 1, 'SELECT t.name FROM events AS e INNER JOIN event_types AS t ON t.id = e.event_type WHERE e.outcome = 1 AND e.id = [value_1];'),
  (820, 'Get acting spacecraft', '[N R L 820 query]: Returns the ID of the spacecraft whose action caused event N.', 1, 'SELECT a.drone FROM events AS e INNER JOIN actions AS a ON a.id = e.action WHERE e.outcome = 1 AND e.id = [value_1];'),
  (821, 'Get associated protocol', '[N R L 821 query]: Returns the ID of the protocol whose action caused event N.', 1, 'SELECT a.protocol FROM events AS e INNER JOIN actions AS a ON a.id = e.action WHERE e.outcome = 1 AND e.id = [value_1];'),
  (831, 'Get affected spacecraft', '[N R L 831 query]: Return the ID of the spacecraft affected by event N.', 1, 'SELECT drone FROM events WHERE outcome=1 AND id=[value_1];'),
  (832, 'Get affected resource', '[N R L 832 query]: Returns the ID of the resource affected by event N.', 1, 'SELECT resource FROM events WHERE outcome = 1 AND id = [value_1];'),
  (840, 'Get new quantity', '[N R L 840 query]: Returns the new quantity set by event N.', 1, 'SELECT new_quantity FROM events WHERE outcome = 1 AND id = [value_1];'),
  (841, 'Get new credits', '[N R L 841 query]: Returns the new credits set by event N.', 1, 'SELECT new_credits FROM events WHERE outcome = 1 AND id = [value_1];'),
  (842, 'Get new location', '[N R L 842 query]: Returns the new location set by event N.', 1, 'SELECT new_location FROM events WHERE outcome = 1 AND id = [value_1];'),
  (843, 'Get event time', '[N R L 843 query]: Returns when event N happened, in seconds since 1970.', 1, 'SELECT UNIX_TIMESTAMP(timestamp) FROM events WHERE outcome = 1 AND id = [value_1];');
